#!/usr/bin/env bash
# Move a legacy data/ folder out of an installed copy of this skill into the
# data folder, so the skills installer cannot delete it.
#
# Usage: migrate.sh --from <installed skill folder>
#
# Safe to rerun, including after an interruption: it backs up the legacy folder
# first, copies only files the data folder lacks, verifies each copy byte for
# byte, and never overwrites. A file present in both places with different
# content stops the migration with the legacy folder untouched. On success the
# legacy folder is renamed to data.migrated-<timestamp>.
# Generated by share-skill from templates/migrate.sh; edit the template.
set -euo pipefail

main() {
  local name="find-hotel"
  if [ "${1:-}" != "--from" ] || [ -z "${2:-}" ]; then
    echo "Usage: migrate.sh --from <installed skill folder>" >&2
    exit 2
  fi
  local install src root data real_data stamp backup
  install="$(cd -P "$2" && pwd -P)"
  src="$install/data"
  if [ ! -d "$src" ] || [ -L "$src" ]; then
    echo "Nothing to migrate: no data/ folder in $install"
    return 0
  fi
  root="${XDG_CONFIG_HOME:-$HOME/.config}/hartreeworks-skills"
  data="$root/$name"
  mkdir -p "$data"
  real_data="$(cd -P "$data" && pwd -P)"
  case "$real_data/" in
    "$install/"*)
      echo "Refusing: the data folder $data resolves inside the installation $install." >&2
      exit 1 ;;
  esac

  # Temp files left by an interrupted run never replaced a real file; drop them.
  find "$data" -name '*.migrating.*' -type f -exec rm -f {} +

  stamp="$(date +%Y%m%d-%H%M%S)"
  backup="$root/.backups/$name-$stamp-$$"
  mkdir -p "$backup"
  cp -Rp "$src/." "$backup/"

  local copied=0 same=0 conflicts=0 f rel dest tmp
  while IFS= read -r -d '' f; do
    rel="${f#"$src"/}"
    dest="$data/$rel"
    if [ -e "$dest" ]; then
      if cmp -s "$f" "$dest"; then
        same=$((same + 1))
      else
        echo "CONFLICT: $rel differs between $src and $data" >&2
        conflicts=$((conflicts + 1))
      fi
      continue
    fi
    mkdir -p "$(dirname "$dest")"
    tmp="$dest.migrating.$$"
    cp -p "$f" "$tmp"
    if ! cmp -s "$f" "$tmp"; then
      rm -f "$tmp"
      echo "Copy of $rel failed verification; stopped. Backup: $backup" >&2
      exit 1
    fi
    mv "$tmp" "$dest"
    copied=$((copied + 1))
  done < <(find "$src" -type f ! -name .DS_Store -print0)

  if [ "$conflicts" -gt 0 ]; then
    echo "Stopped: $conflicts conflicting file(s). Nothing was overwritten and $src is untouched (backup: $backup)." >&2
    echo "Keep the version you want in $data, delete the other, then rerun." >&2
    exit 1
  fi
  mv "$src" "$install/data.migrated-$stamp"
  echo "Migrated $src to $data: $copied copied, $same already there. Backup: $backup"
}

main "$@"
